-- 2026-08-28: solid_of_revolution explore sandbox (Rule 37) + tick-container rect,
-- plus two RECURRENCE upserts of already-FIXED classes (text appended, never replaced).
-- Generated by src/scripts/_seed_engine_bug_queue_sr_explore_idle_turn.ts — idempotent.

INSERT INTO engine_bug_queue (bug_class, title, severity, owner_cluster, root_cause, prevention_rule, probe_type, probe_logic, status, concepts_affected, fixed_in_files, discovered_in_session, row_type) VALUES
('field3d_rule37_idle_motion_inside_a_rotationally_symmetric_solid_is_invisible_and_scores_zero', 'solid_of_revolution shipped an explore sandbox with no idle motion (0px/1s against a 60px floor), and the obvious fix — turning the solid about its own axis — is provably zero motion, while turning the region INSIDE it is real motion a perceptual diff still scores as zero', 'MAJOR', 'peter_parker:field3d_surgeon', 'FIXED 2026-08-28 on the first concept to author the scenario (solids_of_revolution, PR #162). Three layers, and only the first is the one anybody writes down. (1) THE OMISSION: the skeleton S9 row asked for a solid that "turns slowly and continuously from t = 0", and the build shipped every other item in that row and not the turn, so the sandbox sat dead still until the teacher first dragged a slider — founder_drive measured 0 changed px over 1 s against its 60 px floor. (2) THE SYMMETRY TRAP, which is why the design line could not be executed literally: a solid of revolution is rotationally symmetric ABOUT ITS AXIS, so turning the swept skin maps the surface onto itself and changes essentially no pixels at all. Measured in the gate over 720 samples: the rotated surface sits 0.00 px from the original as a set. The motion that is both real and true to the concept is the flat GENERATING REGION still sweeping inside the closed solid. (3) THE ONE THAT COST THE CYCLE: that motion was implemented, verified live at exactly 30 deg/s (PM_srTurnDeg 264.0 -> 294.2 over one second), drawn last so it reads over the solid — and founder_drive STILL reported 0 px. Its pixelmatch threshold (0.1) is PERCEPTUAL, and the region (#4FC3F7) sweeps inside a disc stack (#B39DDB) of almost exactly its luminance (Y 166 vs 171): the same frame pair scores 9 034 changed px at threshold 0.05 and 0 at 0.1. Anything that moves INSIDE a closed solid of revolution stays inside its silhouette, and the silhouette is where the contrast against the background lives. The shipped fix is both motions: the region turn (the one that teaches) plus a slow sandbox ORBIT at the bonding_scene / orbital_shapes idle rate (0.14 rad/s), which moves the silhouette. Measured after: 4 369 px / 1 s, flag gone.', 'A Rule-37 idle motion is not done when it exists; it is done when it is MEASURED on the composited frame. (a) Pick the motion from the object geometry FIRST: on a rotationally symmetric object, rotation about the symmetry axis is a no-op, and the gate must own that as a negative control rather than a comment. (b) Prefer the object own motion (this concept vocabulary: the generator still sweeping) and add the camera orbit ONLY on evidence that the first cannot clear the floor — the evidence being a founder_drive number, not an opinion. (c) Any motion that lives INSIDE a closed translucent body must be checked for LUMINANCE contrast, not just for existence: a perceptual diff is entitled to call a chromatic-only change no change, and so is a teacher glancing at the screen. (d) Every angle stays a closed form on state-local ms and explore-only, so guided baselines and SET_TIME_FREEZE re-pins are untouched by construction. (e) The camera, if it drifts, is surrendered to the teacher on the first drag and taken back only on state entry (the organic_structure seize edge) — a clear that re-runs per frame kills orbiting after the first touch.', 'js_eval', 'founder_drive motionProbe on the explore state, SHOT BEFORE ANY DRAG, clipped to the sim: two frames 1 s apart, pixelmatch threshold 0.1, floor 60 px. Measured on solids_of_revolution: BEFORE 0 px (EXPLORE_FROZEN flagged); region turn alone 0 px at threshold 0.1 but 9 034 px at 0.05 (the chromatic-only signature); AFTER, with the sandbox orbit, 4 369 px (0.661%) and no flag. Gate-side (check:solid-of-revolution section 16, 8 negative controls): the idle angle returns 0 for every guided mode at 6 sample times; explore is exact, wrapped into [0,360) and identical on a 3000 -> 9000 -> 3000 re-pin; the closed skin rotated by one second of turn sits 0.00 px from itself as a 720-point set (the symmetry control); the region strip rasterised at 1280x720 changes at least 4 723 px of its own silhouette at every phase; and the wiring assertions pin the turn to the region mesh and keep the swept skin on its closed 360.', 'FIXED', ARRAY['solids_of_revolution'], ARRAY['src/lib/renderers/field_3d_renderer.ts', 'src/scripts/check_solid_of_revolution.ts'], 'session_2026-08-28_sr_checkpoint_b', 'incident'),
('field3d_full_viewport_overlay_container_has_no_ink_but_its_rect_collides_with_all_review_chrome', 'The #sr_ticks tick-number container was a 100% x 100% position:fixed sheet, so a DOM collision probe scored a transparent container carrying no ink against every piece of review chrome — 27 collisions across 9 states', 'MODERATE', 'peter_parker:field3d_surgeon', 'FIXED 2026-08-28. The DOM tick numbers are absolutely positioned children written per frame from nlbProjPx in VIEWPORT pixels, so their parent needs to be nothing but an origin. It was built as position:fixed;left:0;top:0;width:100%;height:100% — a full-screen transparent sheet with pointer-events:none. Nothing renders in it, but its BOUNDING RECT is the whole viewport, and a collision probe measures rects: founder_drive reported sr_ticks x #fsBtn, x #wgBtn and x #simPenBar on all nine states, 27 findings for an element that cannot overlap anything. The real ticks, which are what a probe should be measuring, went unmeasured behind it.', 'A container that carries no ink of its own gets an EMPTY rect: width:0;height:0;overflow:visible, keeping left:0;top:0 so viewport-positioned children land on the identical pixel. Then a DOM probe measures the glyphs, which can genuinely collide, instead of the sheet, which cannot. The general form: any position:fixed overlay parent sized in percentages is a probe hazard unless it paints; size the thing that paints.', 'js_eval', 'founder_drive probeChromeCollisions across every state: intersect each declared overlay rect with the review chrome rects (#fsBtn, #wgBtn, #simPenBar) and report overlaps wider and taller than 4 px. Measured on solids_of_revolution: BEFORE 27 collisions (3 chrome elements x 9 states, all sr_ticks), AFTER 0, with the tick glyphs rendering at the identical pixels. Gate-side: check:solid-of-revolution section 16 (v) asserts the shipped cssText is a 0x0 fixed box with overflow visible and no percentage, with the pre-fix string as the negative control.', 'FIXED', ARRAY['solids_of_revolution'], ARRAY['src/lib/renderers/field_3d_renderer.ts', 'src/scripts/check_solid_of_revolution.ts'], 'session_2026-08-28_sr_checkpoint_b', 'incident'),
('field3d_explore_sandbox_with_no_authored_spin_is_byte_static_and_fails_the_rule37_probe', 'orbital_shapes had no explore idle-spin fallback, so an untouched sandbox produced identical frames', 'MODERATE', 'peter_parker:field3d_surgeon', 'The spin rate fell back to 0 with no explore branch, so a sandbox authoring no spin_rate produced byte-identical frames and would fail the Rule-37 motion probe at Checkpoint B. The headless harness never drags, so an explore state that only moves under a teacher hand reads as dead. || RECURRENCE 2026-08-28 (solid_of_revolution, the next NEW field_3d scenario after this row was closed): the sandbox shipped byte-static again and founder_drive flagged EXPLORE_FROZEN at 0 px / 1 s. The fix that closed this row is a bonding_scene-LOCAL fallback (spinRate = 0.14 when an explore state authors none), so it protects exactly one scenario and cannot reach a new one — a per-scenario fallback is not a fleet invariant however well it is written. The recurrence carried its own new knowledge and is filed separately as field3d_rule37_idle_motion_inside_a_rotationally_symmetric_solid_is_invisible_and_scores_zero; this row is updated rather than duplicated because the CLASS is the same one.', 'The idle fallback gates on ABSENCE of the authored value, not on value <= 0: a concept that authors 0 deliberately is asking for a still sandbox, and a >0 test would override the author. Copy the intent of a sibling scenario fallback, not its predicate. || AND IT MUST BE CHECKED AT BUILD TIME, NOT INHERITED: every NEW field_3d scenario declares its explore idle motion explicitly and proves it with a founder_drive motion number before Checkpoint B. Do not assume another scenario fallback covers you — none of them are fleet-wide.', 'js_eval', 'Capture an explore state with no spin_rate at two pins and assert the frames differ; capture a guided state with no spin_rate at two pins and assert they are identical. || 2026-08-28 recurrence measurement (solids_of_revolution): BEFORE 0 px / 1 s, AFTER 4 369 px / 1 s (floor 60).', 'FIXED', ARRAY['atomic_orbitals_s_p_d', 'atomic_and_ionic_radius', 'ionisation_enthalpy', 'solids_of_revolution'], ARRAY['src/lib/renderers/field_3d_renderer.ts', 'src/scripts/check_solid_of_revolution.ts'], 'original session not recorded (overwritten 2026-08-28) | RECURRED solid_of_revolution 2026-08-28 (session_2026-08-28_sr_checkpoint_b)', 'incident'),
('f3d_widget_autolabel_contradicts_the_panel_header_it_toggles', 'The Rule-39g auto-discovered widget list labelled the work-bar panel "Energy" while the panel header read "Work done", and printed id abbreviations ("Annots", "Slowmo") as teacher-facing English', 'MODERATE', 'peter_parker:field3d_surgeon', 'FIXED 2026-08-02. The generic widget engine derives every teacher-facing label from the DISCOVERED ELEMENT ID (pmWgPanelLabel -> pmWgPanelWords), which names what a panel was CALLED when it was written, not what it SHOWS now. Two failure modes, both confirmed from a live WIDGET_DECLARE capture on the built review page. (1) REUSE ROT: SEAM M reused SEAM L energy panel #nlb_energy to carry the signed WORK ledgers, so the id outlived its contents and the gear row read "Energy" over a panel whose own rendered header reads "Work done" — on positive_negative_zero_work, a concept that deliberately bans the word energy from every reader-facing string because that word is its boundary with work_energy_theorem. Nothing in the engine could have caught it: an id is not evidence about content. (2) ABBREVIATION: an id is written for code and abbreviates freely, so the same fallback printed "Annots" for #f3d_annots and "Slowmo" for #nlb_slowmo, which are not English words (Rule 41) in a list a teacher reads. The data-wg-label self-declaration hook already existed for panels but was read by NOTHING in the fleet and was not honoured for slider rows at all. || RECURRENCE 2026-08-28 (solid_of_revolution): the gear panel auto-derived "Axis of revolution slider" for #sr_axis_row, which is a two-BUTTON toggle (about x / about y) and not a slider at all — the same contradiction between the derived label and the thing it toggles, in the row-label half of the resolver this time. The scenario already curated data-wg-label on its three DOM panels and simply did not put one on the row, and nothing in the pipeline asks a new scenario whether it did. Fixed the same day by the one attribute (data-wg-label="Axis of revolution"), never by a special case in the shared engine.', 'The id-derived label is the LAST resort and carries two guarantees only: it is spelled in whole English words, and it never survives a panel that knows better. (a) SELF-DECLARATION is authoritative — any element that knows its own teacher-facing name sets data-wg-label on the discovered node and the engine reads it in preference to everything else, for slider rows as well as panels. This is not the curated 39a path: no SIM_READY list, no per-concept authoring, so Rule 39f/g still holds (a new scenario inherits the gear panel for free). (b) A self-declared label is computed CONCEPT-WIDE, from what the concept authors, never from the state that happens to be applied first — the engine captures a label once at declaration and the review chrome only re-renders the list when the KEY SET changes, so a per-state label is both unstable under Rule 25d state reordering and unable to update itself later. (c) A panel whose contents outlive its id must name what it SHOWS and share a stem with the header it renders, so the gear row and the thing it toggles read as the same object. (d) The id fallback expands known abbreviated stems (whole-token match only, never a substring) before it capitalises. Corollary observed while fixing and NOT part of this row: #nlb_energy and #f3d_annots are declared as toggles on all 12 newtons_laws_body concepts including the 10 that author neither block and the concepts that author no annotations, because a dynamic position:fixed panel is declared on sight rather than on first visibility — a phantom-widget defect of its own class, unfixed. || (e) A ROW WHOSE CONTROL IS NOT A SLIDER MUST SELF-DECLARE: the id fallback appends " slider" to the label text of a row, which is right for a range input and a lie for a button pair, a select or a checkbox. Every new scenario checks its own live WIDGET_DECLARE / SIM_READY.widgets payload against the controls it actually built, as part of the build, rather than waiting for a reviewer to read the gear panel.', 'js_eval', 'Capture the WIDGET_DECLARE (generic engine) and SIM_READY.widgets (curated 39a) payloads on the built review page, walking every state on the rail so late-revealed widgets declare. For each entry, resolve the element in the sim iframe and take its first visible short text-bearing leaf as the rendered header; where such a header exists, assert the declared label shares a stem with it. Independently assert every declared label is whole English words: reject any token that is a known abbreviation or is not in a dictionary. Measured 2026-08-02, positive_negative_zero_work before -> after: nlb_energy "Energy" -> "Work done" (header "Work done"), f3d_annots "Annots" -> "Annotations", nlb_slowmo "Slowmo" -> "Slow motion"; work_done_by_constant_force identical; normal_force nlb_energy "Energy" -> "Energy bars" (that concept authors neither block and the panel never becomes visible, so no header exists to match); capacitance emits ZERO WIDGET_DECLARE and its curated 7-entry SIM_READY list is byte-identical, which is the collateral-damage proof. Labels are chrome, never sim pixels: THE EYE H2 must be flat. || 2026-08-28 recurrence, measured on the live built page (solids_of_revolution): the declared entry for sr_axis_row read "Axis of revolution slider" before and reads {"key":"sr_axis_row","label":"Axis of revolution"} after, with the five real slider rows unchanged ("Curve height a slider", "Far end b slider", "Radius r slider", "Discs n slider", "Cut at x slider").', 'FIXED', ARRAY['positive_negative_zero_work', 'work_done_by_constant_force', 'connected_bodies', 'friction_force', 'block_on_incline', 'normal_force', 'tension_force', 'newton_first_law', 'newton_second_law', 'newton_third_law', 'free_body_diagram', 'rolling_friction', 'solids_of_revolution'], ARRAY['src/lib/renderers/field_3d_renderer.ts', 'src/scripts/check_solid_of_revolution.ts'], 'session_2026-08-02_wg_autolabel_selfdeclare | RECURRED solid_of_revolution 2026-08-28 (session_2026-08-28_sr_checkpoint_b)', 'incident')
ON CONFLICT (bug_class) DO UPDATE SET status = EXCLUDED.status, root_cause = EXCLUDED.root_cause,
  prevention_rule = EXCLUDED.prevention_rule, probe_logic = EXCLUDED.probe_logic,
  title = EXCLUDED.title, severity = EXCLUDED.severity, owner_cluster = EXCLUDED.owner_cluster,
  concepts_affected = EXCLUDED.concepts_affected, fixed_in_files = EXCLUDED.fixed_in_files,
  fixed_at = CASE WHEN EXCLUDED.status = 'FIXED' THEN now() ELSE engine_bug_queue.fixed_at END;
